/**
 * GPU-compressed variants of the library's textured files (`assets/ktx2.json`, generated by
 * `scripts/assets/ktx2.ts` with KTX-Software).
 *
 * Every model whose textures can be block-compressed has a twin under `k/`: the same GLB with its
 * images replaced by KTX2 / Basis Universal textures (`KHR_texture_basisu`; ETC1S or UASTC, full
 * mip chains, sRGB colour and linear data). A renderer that can transcode Basis loads the twin and
 * keeps the textures compressed on the GPU (BC7 / BC1 / ETC / ASTC instead of RGBA8: about a
 * quarter of the memory or less); anything else loads the original file, so the index is purely
 * an optimisation and every lookup may return null.
 *
 * The index is loaded lazily (its own chunk, like the catalog) and keyed by the original file's
 * library path. Each entry records the SHA-256 of the variant and of the source it was made from,
 * so a stale variant (the library was rebuilt, the variant was not) is caught by the tests.
 */
import { z } from 'zod';
import { LibraryPath } from './schema';
import { getCatalog, libraryPathOf, libraryUrl } from './registry';

const Hex64 = z.string().regex(/^[0-9a-f]{64}$/);

/** Variant file path relative to the catalog base: `k/sofa.0123abcd.glb`. */
export const VariantPath = z.string().regex(/^k\/[a-z0-9_-]{1,64}\.[0-9a-f]{8}\.glb$/, 'variant paths are content-hashed GLBs under k/');

/** How one texture of a variant was stored. */
export const VariantTexture = z.object({
  /** glTF material slots the texture fills (`baseColorTexture`, `normalTexture`, …). */
  slots: z.array(z.string().min(1).max(48)).min(1).max(8),
  /** `etc1s` (Basis LZ), `uastc` (UASTC + Zstandard) or `kept` (left in its source format, with the reason). */
  codec: z.enum(['etc1s', 'uastc', 'kept']),
  width: z.number().int().min(1).max(8192),
  height: z.number().int().min(1).max(8192),
  /** Structural similarity of mip level 0 against the source (luma-weighted over R, G, B; encoded textures). */
  ssim: z.number().min(-1).max(1).optional(),
  reason: z.string().max(120).optional(),
});
export type VariantTexture = z.infer<typeof VariantTexture>;

export const TextureVariant = z.object({
  file: VariantPath,
  sha256: Hex64,
  bytes: z.number().int().min(1),
  /** The original file the variant was made from. */
  source: z.object({ sha256: Hex64, bytes: z.number().int().min(1) }),
  textures: z.array(VariantTexture).min(1).max(64),
  /**
   * Estimated GPU bytes of the file's textures with full mip chains: `before` as RGBA8, `after`
   * as transcoded on a desktop GPU (BC7 for UASTC and ETC1S; kept textures count as RGBA8).
   */
  gpu: z.object({ before: z.number().int().min(0), after: z.number().int().min(0) }),
});
export type TextureVariant = z.infer<typeof TextureVariant>;

export const TextureVariants = z.object({
  version: z.literal(1),
  /** The encoder (KTX-Software, Apache-2.0) and the settings the files were made with. */
  encoder: z.object({ name: z.string().max(60), version: z.string().max(20), licence: z.string().max(40), settings: z.record(z.string(), z.string().max(200)) }),
  entries: z.record(LibraryPath, TextureVariant),
});
export type TextureVariants = z.infer<typeof TextureVariants>;

const EMPTY: TextureVariants = { version: 1, encoder: { name: 'none', version: '0', licence: 'none', settings: {} }, entries: {} };

let current: TextureVariants | null = null;
let loading: Promise<TextureVariants> | null = null;

/** Install an index (validated); `null` clears it. Tests and alternative hosts use this. */
export function setTextureVariants(v: unknown): TextureVariants | null {
  loading = null;
  current = v === null ? null : TextureVariants.parse(v);
  return current;
}

/** The installed index, or null before {@link loadTextureVariants} resolved. */
export function getTextureVariants(): TextureVariants | null {
  return current;
}

/** Load (once) the bundled index. Resolves to an empty index when there is none, so callers never fail. */
export function loadTextureVariants(): Promise<TextureVariants> {
  if (current) return Promise.resolve(current);
  loading ??= import('../../../assets/ktx2.json')
    .then((m: { default: unknown }) => {
      current = TextureVariants.parse(m.default);
      return current;
    })
    .catch(() => {
      current = EMPTY;
      return current;
    });
  return loading;
}

/**
 * URL of the compressed twin of a library file URL (`/assets/lib/m/sofa.0123abcd.glb` →
 * `/assets/lib/k/sofa.89abcdef.glb`), or null when there is none (not a library URL, no variant,
 * index not loaded). Query strings and fragments are never matched.
 */
export function textureVariantUrl(url: string, index: TextureVariants | null = current, base: string = getCatalog()?.base ?? '/assets/lib/'): string | null {
  const rel = index ? libraryPathOf(url, base) : null;
  if (!index || rel === null) return null;
  const hit = Object.hasOwn(index.entries, rel) ? index.entries[rel] : undefined;
  return hit ? libraryUrl(hit.file, { base }) : null;
}

/** Library-relative path of the twin of a library path (`m/sofa.0123abcd.glb` → `k/sofa.89abcdef.glb`), or null. */
export function textureVariantPath(path: string, index: TextureVariants | null = current): string | null {
  if (!index) return null;
  return Object.hasOwn(index.entries, path) ? (index.entries[path]?.file ?? null) : null;
}
